// Title: Convert an Excel workbook to HTML and create a gzipped .html.gz file using Aspose.Cells and GZipStream in C#
// Common Searches: how to export only the first worksheet of an Excel file to HTML with Aspose.Cells in C# | compress HTML generated by Aspose.Cells using GZipStream for optimal web delivery | save an Aspose.Cells workbook as a .html.gz file in a .NET console application | C# code to convert Excel to HTML and then gzip the result | using HtmlSaveOptions and GZipStream together to create compressed HTML from Excel
// Tags: Aspose.Cells HtmlSaveOptions export active worksheet | C# GZipStream HTML compression | Excel to HTML conversion Aspose.Cells | gzip .html.gz file creation .NET | memory stream HTML generation Aspose.Cells

using System;
using System.IO;
using System.IO.Compression;
using Aspose.Cells;

// The console program validates input arguments, loads an Excel workbook with Aspose.Cells, uses HtmlSaveOptions to export the first worksheet as HTML into a memory stream, then compresses the HTML bytes with GZipStream at optimal compression level, writes the result to a .html.gz file, and logs both original and compressed sizes while handling errors.
class Program
{
    static void Main(string[] args)
    {
        // Validate input arguments
        if (args.Length < 1)
        {
            Console.WriteLine("Usage: Program <input_excel_file_path> [output_gzip_file_path]");
            return;
        }

        string inputExcelPath = args[0];
        string outputGzipPath = args.Length >= 2 ? args[1] : Path.ChangeExtension(inputExcelPath, ".html.gz");

        // Verify that the input file exists
        if (!File.Exists(inputExcelPath))
        {
            Console.WriteLine($"Error: The input file \"{inputExcelPath}\" does not exist.");
            return;
        }

        try
        {
            // Load the workbook
            Workbook workbook = new Workbook(inputExcelPath);

            // Prepare HTML save options
            HtmlSaveOptions htmlOptions = new HtmlSaveOptions(SaveFormat.Html);
            // Export only the first worksheet (optional, adjust as needed)
            htmlOptions.ExportActiveWorksheetOnly = true;

            // Save the workbook as HTML into a memory stream
            using (MemoryStream htmlStream = new MemoryStream())
            {
                workbook.Save(htmlStream, htmlOptions);
                byte[] htmlBytes = htmlStream.ToArray();

                Console.WriteLine($"Generated HTML size: {htmlBytes.Length} bytes.");

                // Compress the HTML using GZipStream
                using (FileStream fileOut = new FileStream(outputGzipPath, FileMode.Create, FileAccess.Write))
                using (GZipStream gzipStream = new GZipStream(fileOut, CompressionLevel.Optimal))
                {
                    gzipStream.Write(htmlBytes, 0, htmlBytes.Length);
                }

                FileInfo gzInfo = new FileInfo(outputGzipPath);
                Console.WriteLine($"Compressed GZIP file created at \"{outputGzipPath}\" ({gzInfo.Length} bytes).");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred during processing:");
            Console.WriteLine(ex.Message);
            Console.WriteLine(ex.StackTrace);
        }
    }
}
